import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, Img } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');
