  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparent background option
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings based on total animation frames
  const totalFrames = durationInSeconds * fps;

  // Marching ants animation settings
  const antsSpeed = 1.5;

  // Spinning animation for Claude AI icon (quartic ease-out for realistic wheel deceleration)
  const spinDuration = totalFrames * 0.7;
